#include <stdio.h>

struct Player {
    const char *name;
    int score;
};

int main() {
    struct Player p[] = {{"Ann", 40}, {"Raj", 95}, {"Mia", 72}};
    int n = 3;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (p[j].score < p[j + 1].score) {
                struct Player temp = p[j];
                p[j] = p[j + 1];
                p[j + 1] = temp;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%d. %s %d\n", i + 1, p[i].name, p[i].score);
    }
    return 0;
}
